// Recognises the two marker HINTs `slti x0, x0, 0x5A0/0x5A1`, the magic
// handoff trigger. Pure bit pattern; the same predicate is consumed by the
// QEMU plugin (C) and by the vsim-side PC pre-scan (C++).
//
// rd=x0 integer-computational instructions are architectural NOPs (RISC-V
// HINT space), so marker binaries run unmodified on every engine and on
// real silicon -- unlike the retired `csrwi 0x7C0` markers (MILMB on Andes
// cores).

#include "hybrid/insn_match.h"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include "insn_encoders.hpp"

#include <cstdint>

using hybrid::test::encode_slti;

TEST_CASE("slti x0, x0, 0x5A0 (enter) matches")
{
  const auto insn = encode_slti(0, 0, 0x5A0);
  hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
  CHECK(hybrid_match_handoff_insn(insn, &kind));
  CHECK(kind == HYBRID_HANDOFF_ENTER);
  CHECK(insn == 0x5A002013u);  // pin the published wire encoding
}

TEST_CASE("slti x0, x0, 0x5A1 (exit) matches")
{
  const auto insn = encode_slti(0, 0, 0x5A1);
  hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
  CHECK(hybrid_match_handoff_insn(insn, &kind));
  CHECK(kind == HYBRID_HANDOFF_EXIT);
  CHECK(insn == 0x5A102013u);  // pin the published wire encoding
}

TEST_CASE("other immediates do not match (plain slti HINTs stay free)")
{
  hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
  CHECK_FALSE(hybrid_match_handoff_insn(encode_slti(0, 0, 0x5A2), &kind));
  CHECK_FALSE(hybrid_match_handoff_insn(encode_slti(0, 0, 0), &kind));
}

TEST_CASE("non-zero rd disqualifies (a real slti, not a HINT)")
{
  hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
  CHECK_FALSE(hybrid_match_handoff_insn(encode_slti(3, 0, 0x5A0), &kind));
}

TEST_CASE("non-zero rs1 disqualifies (still a HINT, but not our marker)")
{
  hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
  CHECK_FALSE(hybrid_match_handoff_insn(encode_slti(0, 5, 0x5A0), &kind));
}

TEST_CASE("sltiu (funct3=011) with the marker imm does not match")
{
  const uint32_t insn =
    (0x5A0u << 20) | (0u << 15) | (0b011u << 12) | (0u << 7) | 0x13u;
  hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
  CHECK_FALSE(hybrid_match_handoff_insn(insn, &kind));
}

TEST_CASE("the retired CSR markers (csrwi 0x7C0, 0/1) no longer match")
{
  hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
  CHECK_FALSE(hybrid_match_handoff_insn(0x7C005073u, &kind));  // csrwi 0x7C0,0
  CHECK_FALSE(hybrid_match_handoff_insn(0x7C00D073u, &kind));  // csrwi 0x7C0,1
}
########## insn_encoders.hpp ##########
// Encoders that are the inverse of hybrid_match_handoff_insn. Used by the
// hybrid handoff tests (insn_match, csr_trigger, handoff_controller) to
// construct the marker HINTs -- and near-miss variants -- with explicit
// fields.

#pragma once

#include <array>
#include <cstdint>
#include <span>

namespace hybrid::test
{

// slti rd, rs1, imm: OP-IMM (0x13), funct3=010, imm[31:20]. The marker
// HINTs pin rd=rs1=x0; the explicit fields let tests build near-misses.
inline constexpr auto encode_slti(uint32_t rd, uint32_t rs1, uint32_t imm)
  -> uint32_t
{
  return (imm << 20) | (rs1 << 15) | (0b010u << 12) | (rd << 7) | 0x13u;
}

template<std::size_t N>
auto as_bytes(const std::array<uint32_t, N>& a) -> std::span<const uint8_t>
{
  return std::span{reinterpret_cast<const uint8_t*>(a.data()),
                   N * sizeof(uint32_t)};
}

}  // namespace hybrid::test

// Pattern recogniser for the magic handoff marker convention. The same
// predicate runs in two places: the QEMU TCG plugin (C) and the vsim PC
// pre-scan (C++).
//
// The markers are RISC-V HINT instructions: SLTI with rd=x0 discards its
// result, so it is an architectural NOP on every conforming core. Marker
// binaries therefore run unmodified on real silicon and on every engine
// (fast/cycle/hybrid) -- unlike the retired `csrwi 0x7C0` markers, where
// CSR 0x7C0 is MILMB on Andes cores and the exit marker enabled ILM at
// base 0, killing standalone runs. The 12-bit immediate carries the
// marker kind; rs1 is pinned to x0 so each marker is one exact 32-bit
// word. SLTI has no compressed form, so markers are always 4 bytes.

#ifndef HYBRID_INSN_MATCH_H
#define HYBRID_INSN_MATCH_H

#include <stdbool.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef enum
{
  HYBRID_HANDOFF_NONE  = 0,
  HYBRID_HANDOFF_ENTER = 1,  // slti x0, x0, 0x5A0
  HYBRID_HANDOFF_EXIT  = 2,  // slti x0, x0, 0x5A1
} hybrid_handoff_kind;

// slti x0, x0, imm: OP-IMM (0x13), funct3=010, rd=rs1=x0, imm[31:20].
#define HYBRID_MARKER_ENTER_INSN 0x5A002013u
#define HYBRID_MARKER_EXIT_INSN  0x5A102013u

// Returns true when `insn` is one of the two marker HINTs. On match,
// *out_kind is set to ENTER or EXIT.
static inline bool hybrid_match_handoff_insn(uint32_t insn,
                                             hybrid_handoff_kind* out_kind)
{
  if (insn == HYBRID_MARKER_ENTER_INSN) {
    *out_kind = HYBRID_HANDOFF_ENTER;
    return true;
  }
  if (insn == HYBRID_MARKER_EXIT_INSN) {
    *out_kind = HYBRID_HANDOFF_EXIT;
    return true;
  }
  return false;
}

#ifdef __cplusplus
}  // extern "C"
#endif

#endif  // HYBRID_INSN_MATCH_H

